script:
(function () {
  'use strict';

  var mirroredVideo = document.getElementById('mirroredVideo');
  var naturalVideo = document.getElementById('naturalVideo');
  var mirroredWrap = document.getElementById('mirroredWrap');
  var naturalWrap = document.getElementById('naturalWrap');
  var placeholderMirrored = document.getElementById('placeholderMirrored');
  var placeholderNatural = document.getElementById('placeholderNatural');
  var overlayMirrored = document.getElementById('overlayMirrored');
  var overlayNatural = document.getElementById('overlayNatural');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var selectView = document.getElementById('selectView');
  var rangeZoom = document.getElementById('rangeZoom');
  var valueZoom = document.getElementById('valueZoom');
  var rangeBrightness = document.getElementById('rangeBrightness');
  var valueBrightness = document.getElementById('valueBrightness');
  var selectFilter = document.getElementById('selectFilter');
  var checkFlipV = document.getElementById('checkFlipV');
  var checkGrid = document.getElementById('checkGrid');
  var checkMaxRes = document.getElementById('checkMaxRes');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var readView = document.getElementById('readView');
  var readOthers = document.getElementById('readOthers');
  var readText = document.getElementById('readText');
  var readResolution = document.getElementById('readResolution');
  var readZoom = document.getElementById('readZoom');
  var readBrightness = document.getElementById('readBrightness');
  var readGrid = document.getElementById('readGrid');
  var readTransform = document.getElementById('readTransform');
  var readFilter = document.getElementById('readFilter');
  var FILTERS = { none: '', sepia: 'sepia(1)', grayscale: 'grayscale(1)', invert: 'invert(1)', contrast: 'contrast(1.6)', blur: 'blur(3px)' };

  var currentStream = null;
  var currentDeviceId = '';
  var starting = false;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  // ---------- View settings -> CSS ----------

  function zoom() { return parseFloat(rangeZoom.value) || 1; }

  function cssFilter() {
    var parts = [];
    var b = parseFloat(rangeBrightness.value) || 100;
    if (b !== 100) parts.push('brightness(' + (b / 100) + ')');
    if (FILTERS[selectFilter.value]) parts.push(FILTERS[selectFilter.value]);
    return parts.join(' ') || 'none';
  }

  function transforms() {
    var z = zoom(), y = checkFlipV.checked ? -z : z;
    return { mirrored: 'scale(' + (-z) + ', ' + y + ')', natural: 'scale(' + z + ', ' + y + ')' };
  }

  function applyView() {
    var t = transforms(), f = cssFilter();
    // Inline transforms override the .is-mirrored scaleX(-1) rule, so the
    // mirrored panel's own transform keeps the horizontal flip itself.
    mirroredVideo.style.transform = t.mirrored;
    naturalVideo.style.transform = t.natural;
    mirroredVideo.style.filter = f === 'none' ? '' : f;
    naturalVideo.style.filter = f === 'none' ? '' : f;
    var view = selectView.value;
    mirroredWrap.classList.toggle('u-hidden', view === 'natural');
    naturalWrap.classList.toggle('u-hidden', view === 'mirror');
    valueZoom.textContent = zoom().toFixed(1) + 'x';
    valueBrightness.textContent = rangeBrightness.value + '%';
    drawOverlays();
    updateReadout();
  }

  function updateReadout() {
    var view = selectView.value, flip = checkFlipV.checked;
    var viewText = view === 'both' ? 'Both panels side by side' : (view === 'mirror' ? 'Mirror view only' : 'Natural view only');
    readView.textContent = viewText + (flip ? ', flipped vertically' : '');
    readOthers.textContent = 'The natural view' + (view === 'mirror' ? ' (hidden right now)' : '') + ' — this page never changes your outgoing video';
    var up = flip ? ' and upside down' : '';
    readText.textContent = view === 'both' ? 'Backwards' + up + ' on the left, correctly' + up + ' on the right'
      : (view === 'mirror' ? 'Backwards' + up + ' (mirror image)' : 'Correctly' + up + ', as others see it');
    readResolution.textContent = naturalVideo.videoWidth ? naturalVideo.videoWidth + '×' + naturalVideo.videoHeight + (checkMaxRes.checked ? ' (max requested)' : ' (default)') : '—';
    readZoom.textContent = zoom().toFixed(1) + 'x';
    readBrightness.textContent = rangeBrightness.value + '%';
    readGrid.textContent = checkGrid.checked ? 'On (rule of thirds)' : 'Off';
    var t = transforms();
    readTransform.textContent = t.mirrored + ' / ' + t.natural;
    readFilter.textContent = cssFilter();
  }

  // ---------- Overlay: rule-of-thirds grid ----------

  function sizeOverlay(c, video) {
    var w = video.videoWidth || 1280, h = video.videoHeight || 720;
    if (c.width !== w || c.height !== h) { c.width = w; c.height = h; }
    return { w: w, h: h };
  }

  function drawOverlay(c, video) {
    var d = sizeOverlay(c, video);
    var g = c.getContext('2d');
    g.clearRect(0, 0, d.w, d.h);
    if (!currentStream) return;
    var lw = Math.max(1, Math.round(d.w / 640));
    if (checkGrid.checked) {
      g.save();
      g.strokeStyle = 'rgba(255,255,255,0.75)';
      g.lineWidth = lw;
      g.shadowColor = 'rgba(0,0,0,0.6)';
      g.shadowBlur = 2;
      g.beginPath();
      [1, 2].forEach(function (i) {
        g.moveTo(d.w * i / 3, 0); g.lineTo(d.w * i / 3, d.h);
        g.moveTo(0, d.h * i / 3); g.lineTo(d.w, d.h * i / 3);
      });
      g.stroke();
      g.restore();
    }
  }

  function drawOverlays() {
    drawOverlay(overlayMirrored, naturalVideo);
    drawOverlay(overlayNatural, naturalVideo);
  }

  // ---------- Camera acquisition / teardown ----------

  // Every camera page on this site copies this stopStream()/error pattern
  // from webcam-test-online.json (see this project's own CLAUDE.md). This
  // tool has no device dropdown-triggered restart complexity beyond the
  // usual, but note it assigns the SAME stream to two <video> elements --
  // stopping the one shared stream releases both at once.
  function stopStream() {
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    mirroredVideo.srcObject = null;
    naturalVideo.srcObject = null;
    mirroredWrap.classList.remove('is-active');
    naturalWrap.classList.remove('is-active');
    placeholderMirrored.style.display = 'flex';
    placeholderNatural.style.display = 'flex';
    btnStop.disabled = true;
    drawOverlays();
    updateReadout();
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Click the camera icon in your address bar (or your browser’s site settings) and allow access, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Make sure a webcam is connected, then reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use.</strong> Another app or browser tab is probably holding it — close video-calling apps or other camera tabs and try again.' };
      case 'OverconstrainedError':
      case 'ConstraintNotSatisfiedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try a different camera from the list above, or untick maximum resolution.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires a secure connection.</strong> Make sure this page is loaded over HTTPS.' };
      case 'AbortError':
        return { sev: 'warn', html: 'The camera request was interrupted. Click <strong>Start Camera</strong> to try again.' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    if (!cams.length) {
      var opt = document.createElement('option');
      opt.value = '';
      opt.textContent = 'No cameras found';
      deviceSelect.appendChild(opt);
      deviceSelect.disabled = true;
      return;
    }
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = false;
  }

  function refreshDeviceList() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return Promise.resolve();
    return navigator.mediaDevices.enumerateDevices().then(populateDeviceSelect).catch(function () {});
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    var videoConstraint = {};
    if (checkMaxRes.checked) { videoConstraint.width = { ideal: 4096 }; videoConstraint.height = { ideal: 2160 }; }
    if (deviceId) videoConstraint.deviceId = { exact: deviceId };
    if (!Object.keys(videoConstraint).length) videoConstraint = true;
    navigator.mediaDevices.getUserMedia({ video: videoConstraint, audio: false })
      .then(function (stream) {
        currentStream = stream;
        // One shared MediaStream feeds both <video> elements -- opening a
        // second independent getUserMedia call for the same physical
        // camera fails on most devices, since it's exclusively locked to
        // the first request. The mirror effect is a pure CSS transform
        // applied to mirroredWrap only; naturalWrap plays the identical
        // stream untouched.
        mirroredVideo.srcObject = stream;
        naturalVideo.srcObject = stream;
        placeholderMirrored.style.display = 'none';
        placeholderNatural.style.display = 'none';
        mirroredWrap.classList.add('is-active');
        naturalWrap.classList.add('is-active');
        return Promise.all([
          mirroredVideo.play().catch(function () {}),
          naturalVideo.play().catch(function () {}),
        ]).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        currentDeviceId = settings.deviceId || deviceId || '';
        btnStop.disabled = false;
        applyView();
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> The left panel shows what you see of yourself; the right panel shows what call participants actually see.' }]);
        return refreshDeviceList();
      })
      .catch(function (err) {
        setDiagnostic([describeError(err)]);
      })
      .finally(function () {
        starting = false;
        btnStart.disabled = false;
      });
  }

  // ---------- Wiring ----------

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped. Click <strong>Start Camera</strong> to test again.' }]);
  });
  deviceSelect.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value);
  });
  checkMaxRes.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value);
  });
  [selectView, selectFilter, checkFlipV, checkGrid].forEach(function (el) {
    el.addEventListener('change', applyView);
  });
  [rangeZoom, rangeBrightness].forEach(function (el) { el.addEventListener('input', applyView); });
  naturalVideo.addEventListener('loadedmetadata', function () {
    drawOverlays();
    updateReadout();
  });
  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  // Overlay canvases keep the video's aspect ratio inside each 16:9 panel
  // (the shared .media-preview canvas rule stretches them to 100% x 100%).
  overlayMirrored.style.objectFit = 'contain';
  overlayNatural.style.objectFit = 'contain';
  applyView();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    btnStart.disabled = true;
  }
})();
